/* playback/rate.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  function clampPlaybackRate(value) {
    const n = Number(value);
    if (!Number.isFinite(n)) return 1;
    return P.clamp(Math.round(n / P.PLAYBACK_RATE_STEP) * P.PLAYBACK_RATE_STEP, P.PLAYBACK_RATE_MIN, P.PLAYBACK_RATE_MAX);
  }

  function normalizePitchMode(id) {
    return P.PLAYBACK_PITCH_MODES.some((m) => m.id === id) ? id : "preserve";
  }

  function applyPlaybackRate() {
    const rate = P.clampPlaybackRate(P.state.playbackRate);
    P.state.playbackRate = rate;
    P.state.pitchMode = P.normalizePitchMode(P.state.pitchMode);
    const preserve = P.state.pitchMode !== "vinyl"; // tape/preserve keep stable pitch; vinyl shifts pitch with rate
    P.state.preservePitch = preserve;
    try { P.audio.playbackRate = rate; } catch {}
    try { P.audio.defaultPlaybackRate = rate; } catch {}
    if (P.audio.preservesPitch !== undefined) P.audio.preservesPitch = preserve;
    if (P.audio.mozPreservesPitch !== undefined) P.audio.mozPreservesPitch = preserve;
    if (P.audio.webkitPreservesPitch !== undefined) P.audio.webkitPreservesPitch = preserve;
  }

  function setPlaybackRate(rate) {
    P.state.playbackRate = P.clampPlaybackRate(rate);
    const match = P.PLAYBACK_RATE_MODES.find((m) => m.rate === P.state.playbackRate);
    P.state.playbackMode = match ? match.id : "custom";
    P.applyPlaybackRate();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function setPlaybackMode(modeId) {
    const mode = P.PLAYBACK_RATE_MODES.find((m) => m.id === modeId);
    if (!mode) { P.state.playbackMode = "custom"; P.syncSettingsUI(); P.saveState(); P.notify("settings"); return; }
    P.state.playbackMode = mode.id;
    P.state.playbackRate = mode.rate;
    P.applyPlaybackRate();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  function setPitchMode(modeId) {
    P.state.pitchMode = P.normalizePitchMode(modeId);
    P.applyPlaybackRate();
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }
  Object.assign(P, { clampPlaybackRate, normalizePitchMode, applyPlaybackRate, setPlaybackRate, setPlaybackMode, setPitchMode });
}
